<script setup lang="ts">
import {ref,reactive,watch,toRaw} from 'vue'
import {ElMessage,ElMessageBox,type FormInstance} from 'element-plus'
import {api,download,type ModuleSpec,type RecordRow} from '../api'
const props=defineProps<{spec:ModuleSpec}>()
const rows=ref<RecordRow[]>([]),total=ref(0),loading=ref(false),q=ref(''),status=ref(''),page=ref(1),dialog=ref(false),detail=ref<RecordRow|null>(null),saving=ref(false),formRef=ref<FormInstance>()
const form=reactive<{id?:number;title:string;status:string;data:Record<string,unknown>;version?:number}>({title:'',status:'待处理',data:{}})
const states=['待处理','进行中','已完成','已关闭','草稿','待审核','已核验','已失效']
const relatedLands=ref<RecordRow[]>([])
watch(()=>props.spec.id,async id=>{if(['expenses','machines','inputs'].includes(id)){try{relatedLands.value=(await api<{items:RecordRow[]}>('/records/lands?size=200')).items}catch{relatedLands.value=[]}}},{immediate:true})
function choosePlot(id:number|undefined){if(id){form.data.plot_id=id;form.data.plot=relatedLands.value.find(l=>l.id===id)?.title}else{delete form.data.plot_id;delete form.data.plot}}
async function load(){loading.value=true;try{const result=await api<{items:RecordRow[];total:number}>(`/records/${props.spec.id}?q=${encodeURIComponent(q.value)}&status=${encodeURIComponent(status.value)}&page=${page.value}`);rows.value=result.items;total.value=result.total}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}
watch(()=>props.spec.id,()=>{page.value=1;q.value='';status.value='';detail.value=null;dialog.value=false;load()},{immediate:true})
function edit(row?:RecordRow){form.id=row?.id;form.title=row?.title||'';form.status=row?.status||'待处理';form.version=row?.version;form.data=row?structuredClone(toRaw(row.data)):Object.fromEntries(props.spec.fields.map(f=>[f.key,f.type==='number'?undefined:'']));dialog.value=true}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;try{await api(`/records/${props.spec.id}${form.id?'/'+form.id:''}`,{method:form.id?'PUT':'POST',body:JSON.stringify(form)});dialog.value=false;ElMessage.success('记录已保存');await load()}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
async function remove(row:RecordRow){try{await ElMessageBox.confirm(`删除“${row.title}”？操作会保留审计记录。`,'删除确认',{type:'warning'});await api(`/records/${props.spec.id}/${row.id}`,{method:'DELETE'});ElMessage.success('已删除');load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
async function exportRows(){try{await download(`/records/${props.spec.id}/export/csv`,`${props.spec.title}.csv`);ElMessage.success('导出成功，CSV 可用 Excel 打开')}catch(e){ElMessage.error((e as Error).message)}}
function display(v:unknown){return v===undefined||v===null||v===''?'—':typeof v==='object'?JSON.stringify(v):String(v)}
</script>
<template>
 <div class="page-title"><div><h1>{{spec.title}}</h1><p>{{spec.group}} · 数据按经营主体或辖区授权隔离</p></div><el-button type="primary" @click="edit()">新增记录</el-button></div>
 <el-alert v-if="spec.note" :title="spec.note" type="info" :closable="false" style="margin-bottom:20px"/>
 <section class="panel"><div class="toolbar"><el-input v-model="q" placeholder="搜索记录标题" clearable style="width:240px" @keyup.enter="page=1;load()"/><el-select v-model="status" placeholder="全部状态" clearable style="width:140px"><el-option v-for="s in states" :key="s" :label="s" :value="s"/></el-select><el-button @click="page=1;load()">查询</el-button><el-button @click="exportRows">导出台账</el-button><span class="muted">共 {{total}} 条</span></div>
 <div class="mobile-records" v-loading="loading"><el-empty v-if="!rows.length" description="暂无记录，点击新增开始建档"/><article v-for="row in rows" :key="row.id" class="record-card"><div class="flex between"><strong>{{row.title}}</strong><el-tag>{{row.status}}</el-tag></div><p class="muted">{{row.demo?'演示记录':'用户录入'}}</p><dl><template v-for="f in spec.fields.slice(0,3)" :key="f.key"><dt>{{f.label}}</dt><dd>{{display(row.data[f.key])}}</dd></template></dl><div class="row-actions"><el-button @click="detail=row">详情</el-button><el-button type="primary" plain @click="edit(row)">编辑</el-button><el-button type="danger" plain @click="remove(row)">删除</el-button></div></article></div><el-table class="desktop-records" :data="rows" v-loading="loading" empty-text="暂无记录，点击新增开始建档"><el-table-column prop="title" label="记录" min-width="200"/><el-table-column v-for="f in spec.fields.slice(0,3)" :key="f.key" :label="f.label" min-width="130"><template #default="{row}">{{display(row.data[f.key])}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='已完成'?'success':'info'">{{row.status}}</el-tag></template></el-table-column><el-table-column label="来源" width="100"><template #default="{row}"><el-tag v-if="row.demo" type="warning">演示</el-tag><span v-else>用户录入</span></template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><div class="row-actions"><el-button link type="primary" @click="detail=row">详情</el-button><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></div></template></el-table-column></el-table>
 <el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="load" style="margin-top:20px"/>
 </section>
 <el-dialog v-model="dialog" :title="form.id?'编辑记录':'新增记录'" width="720px" destroy-on-close><el-form ref="formRef" :model="form" label-position="top"><div class="field-grid"><el-form-item label="记录标题" prop="title" :rules="[{required:true,message:'请填写记录标题',trigger:'blur'}]"><el-input v-model="form.title" maxlength="180" placeholder="例如：01 号温室巡查记录"/></el-form-item><el-form-item label="处理状态"><el-select v-model="form.status" style="width:100%"><el-option v-for="s in states" :key="s" :value="s" :label="s"/></el-select></el-form-item>
 <el-form-item v-if="['expenses','machines','inputs'].includes(spec.id)" label="核算关联地块（可选）"><el-select :model-value="form.data.plot_id" clearable placeholder="不选则计入未关联金额" :disabled="!!form.id&&!!form.data.plot_id" @change="choosePlot"><el-option v-for="l in relatedLands" :key="l.id" :value="l.id" :label="l.title"/></el-select></el-form-item>
 <el-form-item v-for="f in spec.fields" :key="f.key" :label="f.label" :prop="'data.'+f.key" :rules="f.required?[{required:true,message:'请填写'+f.label,trigger:'change'}]:[]" :style="f.type==='textarea'?'grid-column:1/-1':''">
 <el-input-number v-if="f.type==='number'" v-model="(form.data[f.key] as number)" :precision="3" :min="['temperature','elevation'].includes(f.key)?undefined:0" :max="['humidity','soil','moisture','impurity'].includes(f.key)?100:undefined" style="width:100%"/>
 <el-select v-else-if="f.type==='select'" v-model="form.data[f.key]" style="width:100%"><el-option v-for="o in f.options" :key="o" :label="o" :value="o"/></el-select>
 <el-date-picker v-else-if="f.type==='date'" v-model="form.data[f.key]" value-format="YYYY-MM-DD" type="date" style="width:100%"/>
 <el-input v-else v-model="(form.data[f.key] as string)" :type="f.type==='textarea'?'textarea':'text'" :rows="3" :placeholder="'填写'+f.label"/>
 </el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
 <el-drawer :model-value="!!detail" @close="detail=null" :title="detail?.title" size="520px"><template v-if="detail"><el-tag :type="detail.demo?'warning':'success'">{{detail.demo?'演示记录':'用户录入'}}</el-tag><el-descriptions :column="1" border style="margin-top:20px"><el-descriptions-item label="状态">{{detail.status}}</el-descriptions-item><el-descriptions-item v-for="f in spec.fields" :key="f.key" :label="f.label"><span class="prewrap">{{display(detail.data[f.key])}}</span></el-descriptions-item><el-descriptions-item label="数据范围">{{detail.org}}</el-descriptions-item><el-descriptions-item label="更新时间">{{detail.updated_at}}</el-descriptions-item></el-descriptions></template></el-drawer>
</template>
